def icon(n):return f'<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="{paths[n]}"/></svg>'
def btn(n,cl=''):return f'<span class="ib {cl}">{icon(n)}</span>'
def avatar(name,cl=''):return f'<span class="av {cl}">{name}</span>'
def wave():return '<span class="wave">'+''.join(f'<i style="height:{v}px"></i>' for v in [8,14,24,17,32,22,12,20,35,28,16,9,22,31,19,13,25,33,22,10,16,26,18,8])+'</span>'
def voice():return f'<div class="voice"><div class="vtop">Голосовое сообщение <span>0:18</span></div><div class="vplay">{btn("play")}{wave()}</div><small>14:32 · доставлено</small></div>'
def nav():return '<div class="bottom">'+''.join(f'<span>{icon(n)}<small>{t}</small></span>' for n,t in [('chat','Чаты'),('people','Люди'),('settings','Настройки')])+'</div>'
def top(title,sub=''):
 return f'<div class="top">{btn("back")}<div><b>{title}</b><small>{sub}</small></div>{btn("more")}</div>'
def header(title,kicker='VOICECHAT'):return f'<div class="heading"><small>{kicker}</small><h3>{title}</h3></div>'
def row(name,msg,time='14:32',initial=None):return f'<div class="person">{avatar(initial or name[0])}<div><b>{name}</b><p>{msg}</p></div><small>{time}</small></div>'
def list_screen(c):
 cl=c[0]
 intro=header('Разговоры' if cl not in ['moss','quiet'] else 'Ваши близкие')
 if cl=='signal':intro=header('На связи.','VOICECHAT / 04')
 if cl=='atelier':intro=header('Добрый вечер.','ВАШ ЛИЧНЫЙ КРУГ')
 if cl=='orbit':intro=header('Привет, Антон!','РАЗГОВОРЫ НАЧИНАЮТСЯ ЗДЕСЬ')
 feature=''
 if cl in ['moss','orbit','quiet']:
  feature='<div class="favorites">'+''.join(f'<div>{avatar(a)}<small>{b}</small></div>' for a,b in [('М','Мама'),('А','Аня'),('П','Папа')])+'</div>'
 if cl=='nocturne':feature=f'<div class="highlight"><small>БЛИЖЕ, ДАЖЕ НА РАССТОЯНИИ</small><b>Услышать своих.</b>{wave()}</div>'
 return f'<div class="listhead">{intro}{btn("plus","add")}</div><div class="search">{icon("search")} Найти разговор</div><div class="tabs"><b>Люди</b><span>Группы</span><span class="counter">3</span></div>{feature}<div class="sectionlabel">НЕДАВНИЕ РАЗГОВОРЫ</div>'+row('Мама','Голосовое · 0:18','14:32')+row('Аня','Давай созвонимся вечером','13:48')+row('Семья','Вы: В воскресенье в пять','12:05','С')+f'<div class="listcta">{icon("plus")} Найти человека</div>'+nav()
def chat_screen(c,record=False,tools=False):
 content=top('Мама','В сети')+f'<div class="callshortcut">{icon("phone")} Позвонить</div><div class="day">Сегодня</div><div class="messages"><div class="bubble">В воскресенье собираемся у нас?<small>14:30</small></div><div class="bubble own">Конечно! Буду к пяти.<small>14:31 · прочитано</small></div>'+voice()+'<div class="bubble">Я приготовлю твой любимый пирог.<small>14:33</small></div></div>'
 if record or tools:content=content.replace('<div class="bubble">Я приготовлю твой любимый пирог.<small>14:33</small></div>', '')
 if record:content+=f'<div class="record"><small>ЗАПИСЬ ГОЛОСА</small><strong>00:12</strong>{wave()}<div class="actions">{btn("trash")}<span>Удалить</span>{btn("stop","primary")}<span>Стоп</span></div></div>'
 elif tools:content+='<div class="tooltray"><b>Добавить в сообщение</b><div>'+''.join(f'<span>{icon(n)}<small>{t}</small></span>' for n,t in [('image','Фото'),('file','Файл'),('video','Видеокружок'),('clock','Отложить'),('chat','Эмодзи'),('clock','Таймер')])+'</div></div>'
 else:content+='<div class="schedulehint">'+icon('clock')+' Запланировано · 2 '+icon('arrow')+'</div>'
 content+=f'<div class="composer">{btn("plus")}<span>Сообщение…</span>{btn("mic")}{btn("send","primary")}</div>'
 if c[0]=='quiet':content+='<div class="helper">«Микрофон» — записать голосовое</div>'
 return content

def specialty(kind,c):
 if kind=='call':
  return top('Голосовой звонок','Можно свернуть')+f'<div class="callbody"><div class="orbitring">{avatar("М")}</div><h3>Мама</h3><p>Разговор</p><strong class="timer">04:32</strong><div class="quality">▂▃▅▆▇ <span>Хорошая связь</span></div></div><div class="calltools">'+''.join(f'<span>{btn(n)}<small>{t}</small></span>' for n,t in [('mic','Микрофон'),('speaker','Динамик'),('video','Камера')])+'</div><div class="hangup">'+icon('phone')+' Завершить</div>'
 if kind=='devices':return top('Устройства','Доступ к аккаунту')+header('Ваш круг доверия.','БЕЗОПАСНОСТЬ')+'<p class="bodytext">Проверяйте новые устройства перед передачей истории.</p>'+card('device','Этот Android','Текущее устройство · проверено')+card('device','Браузер на ноутбуке','Нужно подтвердить')+'<div class="solid">Проверить устройство</div><div class="notice">Отзыв завершает сеанс. Уже сохранённые копии удалить удалённо нельзя.</div>'
 if kind=='group':return top('Семья','4 участника')+'<div class="groupcover">'+avatar('С')+'<h3>Все свои.</h3><p>Один разговор на всех.</p></div>'+row('Мама','В сети','')+row('Аня','Была недавно','')+row('Папа','Был сегодня','')+'<div class="solid">Пригласить человека</div><div class="subactions">Аватар · Название</div><div class="dangertext">Покинуть группу</div>'
 if kind=='schedule':return top('Запланировано','Семья · 2 сообщения')+header('В нужный момент.','ОЧЕРЕДЬ ОТПРАВКИ')+'<div class="timeline"><small>СЕГОДНЯ · 17:00</small><h4>Встречаемся в пять!</h4><p>Ожидает публикации</p><span>Отменить отправку</span></div><div class="timeline"><small>ЗАВТРА · 09:00</small><h4>Доброе утро!</h4><p>Ожидает публикации</p><span>Отменить отправку</span></div><div class="notice">Время устройства. После подтверждения сервером приложение можно закрыть.</div>'
 if kind=='welcome':return '<div class="welcome">'+header('Ближе,<br>даже на расстоянии.','VOICECHAT')+'<p>Разговоры с теми, кто важен.</p></div><div class="form"><b>Добро пожаловать</b><label>Имя пользователя</label><div class="field">anton</div><label>Пароль аккаунта</label><div class="field">••••••••••••</div><div class="solid">Войти</div><p>Создать аккаунт · Забыли пароль?</p><small>В браузере также нужна отдельная локальная фраза для защиты переписки.</small></div>'
 if kind=='security':return top('Безопасность','Устройства и история')+f'<div class="shieldhero">{icon("shield")}<h3>Доступ под контролем.</h3></div>'+card('device','Устройства','2 сеанса · 1 требует проверки')+card('lock','Проверить устройство','QR или сравнение кодов')+card('file','Ключ восстановления','Сохраните отдельно')+card('clock','Запросы истории','1 запрос ожидает ответа')
 if kind=='search':return top('Поиск по истории','Семья')+'<div class="search">'+icon('search')+' воскресенье</div><div class="notice">По загруженной истории. Результаты могут быть неполными.</div><div class="sectionlabel">НАЙДЕНО · 3 СООБЩЕНИЯ</div>'+''.join('<div class="result"><small>'+date+'</small><b>'+txt+'</b><span>Перейти к сообщению →</span></div>' for date,txt in [('Сегодня · Мама','В воскресенье собираемся у нас?'),('18 октября · Антон','В воскресенье я свободен.'),('11 октября · Аня','Фото с воскресной прогулки')])
 if kind=='storage':return top('Локальная копия','Хранилище')+'<div class="storagehero"><div class="donut"><strong>32%</strong><small>от лимита</small></div><h3>Место для разговоров.</h3></div>'+card('file','328 МиБ занято','696 МиБ до лимита')+card('settings','Лимит копии','1024 МиБ')+'<div class="notice">Это лимит локальной истории, не свободное место на диске. Скачанные файлы учитываются отдельно.</div><div class="solid">Проверить и очистить</div>'
 if kind=='recovery':return top('Вернуть историю','Доступ к переписке')+header('Ваши разговоры<br>останутся с вами.')+'<p class="bodytext">Выберите способ восстановления доступа к истории.</p>'+card('device','Через своё устройство','Подтвердите на устройстве, где вы уже вошли.')+card('lock','По ключу восстановления','Используйте сохранённый личный ключ.')+'<div class="notice">Сброс пароля сам по себе не открывает старую переписку.</div><div class="solid">Выбрать устройство</div>'

def card(i,t,s):return f'<div class="infocard">{icon(i)}<div><b>{t}</b><p>{s}</p></div>{icon("arrow")}</div>'
def phone(body,label):return f'<figure><div class="phone"><div class="status"><span>9:41</span><span>••• ▰</span></div><div class="screen">{body}</div><div class="homebar"></div></div><figcaption>{label}</figcaption></figure>'
