preview+='</main>'
previewcss='''body{background:#e7e8e3;padding:30px}.previewhead{padding:10px 15px 25px}.previewhead h1{font:44px Georgia;margin:10px 0}.previewhead p{color:#4b5650}.previewgrid{display:grid;grid-template-columns:repeat(5,360px);gap:25px}.previewgrid>section{background:var(--bg);color:var(--ink);padding:12px;border-radius:20px}.previewgrid h2{font:24px var(--display);margin:8px 4px 20px;letter-spacing:-.5px}.previewgrid figure{margin:0}.previewgrid .phone{height:840px}.previewgrid figcaption{font-size:12px}.previewgrid .screen{padding-inline:12px}.previewgrid .tide .top{margin-inline:-12px}'''
